{"cards": [{"node_code": "N_e1f39416be095ccc", "definition": "研究路基本体构造及其在特殊地质条件下的结构形式，涵盖一般路基、特殊路基及配套的防护支挡结构设计。", "boundary": "本节点聚焦于路基的实体结构组成与构造设计。包括路基横断面、填挖方结构、特殊路基（如软基、岩溶）的结构处理方案，以及为维持结构稳定而设置的防护与支挡结构。边界在于区分“结构实体”与“线位规划”，路线选线归入兄弟节点，纯材料力学归入基础理论。", "includes": ["一般路基与特殊路基的结构形式、断面设计与构造要求", "路基边坡防护、挡土墙、锚杆等支挡结构的设计与计算", "特殊地质条件下路基结构的稳定性分析与加固措施"], "excludes": ["路线平面与纵断面线形设计（归入路线选线/线形节点）", "路面结构层（沥青、混凝土面层）的设计"], "sibling_distinctions": [{"other_code": "N_85cb8f9dd99b40cf", "rule": "本节点侧重结构整体构造及支挡结构的设计原理，兄弟节点侧重具体的防护工程措施（如植被、砌体）的施工与细节。"}, {"other_code": "N_92ceaf10b0ce19fa", "rule": "本节点关注选定线位后的路基结构设计，兄弟节点关注线位选择过程中的地质避让与方案比选。"}], "cross_boundary_rule": "当防护/支挡结构作为路基结构不可分割的一部分时，其设计原则归入本节点；若仅涉及具体施工工艺或独立防护设施，可关联至防护节点。"}, {"node_code": "N_85cb8f9dd99b40cf", "definition": "研究路基边坡及表面的防护工程措施，旨在防止水土流失、冲刷及风化，涵盖植物、工程及综合防护技术。", "boundary": "本节点聚焦于路基表面的保护性工程措施。包括坡面防护（如喷播、砌石、混凝土框格）及特殊环境下的防冲刷、防风化技术。边界在于区分“表面防护”与“内部支挡”，挡土墙等承受土压力的结构归入路基结构节点，排水设施归入排水节点。", "includes": ["路基边坡的植物防护、工程防护（砌体、混凝土、土工材料）技术", "特殊气候或地质条件下的路基表面防冲刷、防冻胀、防盐渍化措施", "防护工程的施工方法、质量检测与维护技术"], "excludes": ["承受侧向土压力的挡土墙、锚杆等支挡结构设计（归入路基结构）", "路基内部或周边的排水系统（边沟、截水沟等）设计"], "sibling_distinctions": [{"other_code": "N_e1f39416be095ccc", "rule": "本节点关注坡面保护与表面稳定，兄弟节点关注路基整体结构及承受土压力的支挡结构。"}, {"other_code": "N_c766fe7e09be8075", "rule": "本节点关注防止水流冲刷坡面的防护，兄弟节点关注引导水流排出路基的排水设施。"}], "cross_boundary_rule": "当防护与排水结合（如带排水孔的砌石护坡），防护主体归入本节点，排水功能细节可关联至排水节点。"}, {"node_code": "N_92ceaf10b0ce19fa", "definition": "研究在特殊地质与气候条件下交通线路的平面与纵断面选线原则，旨在避让不良地质并优化路基工程条件。", "boundary": "本节点聚焦于线路走向与高程的规划决策。包括在软土、岩溶、冻土等特殊区域选线时的避让策略、线位比选及与路基工程的协调。边界在于区分“线位规划”与“结构设计”，具体的路基断面设计归入路基结构节点，线形几何指标归入线形节点。", "includes": ["特殊地质区（滑坡、崩塌、岩溶等）的线路避让与通过方案", "选线过程中的地质勘察、环境评价及多方案技术经济比选", "线位与路基工程、排水防护的协调设计原则"], "excludes": ["路基横断面结构与防护支挡的具体设计（归入路基结构）", "路线平面与纵断面的几何线形指标计算（归入线形节点）"], "sibling_distinctions": [{"other_code": "N_e1f39416be095ccc", "rule": "本节点关注“在哪里修”的线位决策，兄弟节点关注“怎么修”的结构设计。"}, {"other_code": "N_644de02b2445c89b", "rule": "本节点关注宏观线位选择与地质避让，兄弟节点关注微观线形几何参数（如曲线半径、坡度）的确定。"}], "cross_boundary_rule": "当线位选择直接决定路基结构形式（如选线避开软基导致路基变高），选线决策归入本节点，由此产生的高路基结构设计归入路基结构节点。"}]}
